fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both input vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Zip the two vectors together, compare element-wise, and collect into a Vec<bool>
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x < y)
     .collect()
}

